urls={'script':base+'examples/benchmark.py','pdb':base+'examples/5dfr_solv-cube_equil.pdb','amber':base+'wrappers/python/openmm/app/data/amber99sb.xml','water':base+'wrappers/python/openmm/app/data/tip3p.xml','article':'https://developer.nvidia.com/blog/maximizing-openmm-molecular-dynamics-throughput-with-nvidia-multi-process-service/','platform':'https://docs.openmm.org/8.2.0/userguide/library/04_platform_specifics.html','pypi':'https://pypi.org/pypi/openmm/8.2.0/json','plugin':'https://pypi.org/pypi/OpenMM-CUDA-12/8.2.0/json','tag':'https://api.github.com/repos/openmm/openmm/git/ref/tags/8.2.0'}
def read(item):
 k,u=item
 try:
  b=urllib.request.urlopen(u,timeout=25).read(); s=b.decode()
