  if k in ('pypi','plugin'):
   j=json.loads(s);return k,{'requires_python':j['info']['requires_python'],'requires_dist':j['info']['requires_dist'],'files':[{'name':x['filename'],'bytes':x['size'],'sha256':x['digests']['sha256']} for x in j['urls'] if 'manylinux' in x['filename']]}
